WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY discount_pct DESC, id) AS dedup_rank FROM promotions QUALIFY dedup_rank = 1) SELECT id, channel, ends_on, discount_pct, CASE WHEN channel RLIKE '^(store|web)$' THEN 'EXTENDED' WHEN channel RLIKE '^(mobile|partner)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS channel_zone FROM latest ORDER BY id NULLS FIRST, channel DESC;
